  dataPayload: Record<string, any>;
}

export interface Phase2PilotManifest {
  version: string;
  datasetName: string;
  databasePath: string;
  databaseSha256: string;
  symbolCount: number;
  symbols: string[];
  dateRange: {
    startDate: string;
    endDate: string;
    tradingDays: number;
  };
  tableRowCounts: {
    DailyOHLCV: number;
    authoritative_trading_calendar: number;
    historical_investable_universe: number;
    corporate_actions_reconciled: number;
    pit_disclosure_registry: number;
  };
  invariants: {
    zeroNullDelivery: boolean;
    zeroNullTurnover: boolean;
    zeroSyntheticProxies: boolean;
    strictPitTimestamps: boolean;
    calendarSynchronized: boolean;
    survivorshipDocumented: boolean;
  };
  generatedAt: string;
}

/**
 * Validates that an input record obeys strict PIT access constraints:
 * Record availableAt MUST be <= decisionTimestamp.
 */
export function assertRecordPIT(record: { availableAt: string }, decisionTimestamp: string, fieldName: string) {
  if (!record.availableAt) {
    throw new Error(`DATA_INSUFFICIENT: Missing availableAt on ${fieldName}`);
  }
  if (record.availableAt > decisionTimestamp) {
    throw new Error(
      `PIT_LEAKAGE_VIOLATION: ${fieldName} availableAt (${record.availableAt}) is later than decisionTimestamp (${decisionTimestamp})`
    );
  }
}

import * as nodeCrypto from "node:crypto";

export type SecurityStatus = "ACTIVE" | "SUSPENDED" | "DELISTED";
export type CorporateActionType = "SPLIT" | "BONUS" | "DIVIDEND";
export type PITDataKind =
  | "SECURITY" | "INDEX_MEMBERSHIP" | "PRICE"
  | "CORPORATE_ACTION" | "FUNDAMENTAL" | "SHAREHOLDING";

export interface PITProvenance {
  sourceId: string;
  sourceType: string;
  availableAt: string;
  effectiveAt?: string;
  retrievedAt?: string;
  sourceVersion?: string;
  recordHash?: string;
}

export interface PITSecurityRecord extends PITProvenance {
  kind: "SECURITY";
  symbol: string;
  isin?: string;
  listingDate: string;
  delistingDate?: string;
  status: SecurityStatus;
  circuitLowerPct?: number;
  circuitUpperPct?: number;
}

export interface PITIndexMembershipRecord extends PITProvenance {
  kind: "INDEX_MEMBERSHIP";
  indexName: string;
  symbol: string;
  effectiveFrom: string;
  effectiveTo?: string;
  announcementDate?: string;
  effectiveDate?: string;
}

export interface PITPriceRecord extends PITProvenance {
  kind: "PRICE";
  symbol: string;
  timestamp: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  deliveryVolume?: number;
  raw: boolean;
  adjusted?: boolean;
}

export interface PITCorporateActionRecord extends PITProvenance {
  kind: "CORPORATE_ACTION";
  symbol: string;
  actionType: CorporateActionType;
  exDate: string;
  recordDate?: string;
  ratioNumerator?: number;
  ratioDenominator?: number;
  amount?: number;
  effectiveTimestamp: string;
}

export interface PITFundamentalDisclosure extends PITProvenance {
  kind: "FUNDAMENTAL" | "SHAREHOLDING";
  symbol: string;
  fiscalPeriodEnd: string;
  announcementTimestamp?: string;
  fallbackAvailableAt?: string;
  metrics: Record<string, number | string | null>;
}

export interface PITDataset {
  securities: PITSecurityRecord[];
  memberships: PITIndexMembershipRecord[];
  prices: PITPriceRecord[];
  corporateActions: PITCorporateActionRecord[];
  fundamentals: PITFundamentalDisclosure[];
}

export interface PITAuditEvent {
  event: "READ" | "FAIL";
  kind: PITDataKind;
  sourceId?: string;
  symbol?: string;
  simulationAsOf: string;
  availableAt?: string;
  effectiveAt?: string;
  reason?: string;
}

export class PITDataUnavailableError extends Error {
  readonly code = "PIT_DATA_UNAVAILABLE";
  constructor(message: string, readonly symbol?: string, readonly asOf?: string) {
    super(message); this.name = "PITDataUnavailableError";
  }
}

export class PITLookaheadError extends Error {
  readonly code = "INVALID_LOOKAHEAD_CONTAMINATION";
  constructor(
    message: string,
    readonly sourceId?: string,
    readonly availableAt?: string,
    readonly asOf?: string
  ) {
    super(message); this.name = "PITLookaheadError";
  }
}

export function canonicalize(value: unknown): string {
  if (value === undefined) return "undefined";
  if (value === null) return "null";
  if (typeof value === "number" && !Number.isFinite(value)) {
    throw new Error("Cannot canonicalize non-finite number");
  }
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(",")}]`;
  if (typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([,v]) => v !== undefined)
      .sort(([a],[b]) => a.localeCompare(b));
    return `{${entries.map(([k,v]) => `${JSON.stringify(k)}:${canonicalize(v)}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

export function sha256Canonical(value: unknown): string {
  return nodeCrypto.createHash("sha256").update(canonicalize(value), "utf8").digest("hex");
}

export function isDataKnowable(recordAvailableAt: string, simulationAsOf: string): boolean {
  return recordAvailableAt <= simulationAsOf;
}

function addDays(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00.000Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0,10);
}

export function eodAvailabilityTimestamp(date: string, hhmm = "15:35"): string {
  return `${date}T${hhmm}:00+05:30`;
}

export function filingAvailableAt(
  d: Pick<PITFundamentalDisclosure, "announcementTimestamp"|"fallbackAvailableAt"|"fiscalPeriodEnd">,
  fallbackLagDays = 45
): string {
  if (d.announcementTimestamp) return d.announcementTimestamp;
  if (d.fallbackAvailableAt) return d.fallbackAvailableAt;
  return `${addDays(d.fiscalPeriodEnd, fallbackLagDays)}T23:59:59+05:30`;
}

export class DeterministicTradingCalendar {
  readonly sessions: string[];
  constructor(sessions: string[], readonly timezone = "Asia/Kolkata") {
    this.sessions = [...new Set(sessions)].sort();
  }
  isTradingDay(date: string) { return this.sessions.includes(date); }
  previousTradingDay(date: string) { return [...this.sessions].reverse().find(x => x < date); }
  nextTradingDay(date: string) { return this.sessions.find(x => x > date); }
}

export class PointInTimeDataEngine {
  private readonly eodAnchor: string;
  private readonly fallbackLagDays: number;
  private readonly events: PITAuditEvent[] = [];

  constructor(
    private readonly data: PITDataset,
    options: { eodAvailabilityAnchor?: string; fallbackFundamentalLagDays?: number } = {}
  ) {
    this.eodAnchor = options.eodAvailabilityAnchor ?? "15:35";
    this.fallbackLagDays = options.fallbackFundamentalLagDays ?? 45;
    this.validate();
  }

  get auditEvents() { return [...this.events]; }

  private validate() {
    for (const p of this.data.prices) {
      if (![p.open,p.high,p.low,p.close,p.volume].every(Number.isFinite)) {
        throw new Error(`Invalid numeric price record ${p.symbol}/${p.timestamp}`);
      }
      if (p.low > p.high || p.low > p.open || p.low > p.close ||
          p.high < p.open || p.high < p.close) {
        throw new Error(`Invalid OHLC ${p.symbol}/${p.timestamp}`);
      }
      if (!p.raw) throw new Error(`Source price records must be raw: ${p.symbol}/${p.timestamp}`);
    }
  }

  private guard(
    record: PITProvenance, asOf: string, kind: PITDataKind, symbol?: string
  ) {
    if (!isDataKnowable(record.availableAt, asOf)) {
      const e: PITAuditEvent = {
        event:"FAIL", kind, symbol, sourceId:record.sourceId,
        simulationAsOf:asOf, availableAt:record.availableAt,
        effectiveAt:record.effectiveAt, reason:"FUTURE_READ"
      };
      this.events.push(e);
      throw new PITLookaheadError(
        `Future read blocked: ${record.availableAt} > ${asOf}`,
        record.sourceId, record.availableAt, asOf
      );
    }
    this.events.push({
      event:"READ", kind, symbol, sourceId:record.sourceId,
      simulationAsOf:asOf, availableAt:record.availableAt,
      effectiveAt:record.effectiveAt
    });
  }

  private missing(kind: PITDataKind, message: string, symbol: string, asOf: string): never {
    this.events.push({event:"FAIL", kind, symbol, simulationAsOf:asOf, reason:"DATA_UNAVAILABLE"});
    throw new PITDataUnavailableError(message, symbol, asOf);
  }

  getSecurities(asOf: string) {
    return this.data.securities.filter(s =>
      s.listingDate <= asOf.slice(0,10) &&
      (!s.delistingDate || asOf.slice(0,10) < s.delistingDate)
    ).filter(s => { this.guard(s, asOf, "SECURITY", s.symbol); return true; });
  }

  getIndexMembers(indexName: string, asOf: string) {
    return this.data.memberships.filter(m =>
      m.indexName === indexName &&
      m.effectiveFrom <= asOf.slice(0,10) &&
      (!m.effectiveTo || asOf.slice(0,10) < m.effectiveTo)
    ).filter(m => { this.guard(m, asOf, "INDEX_MEMBERSHIP", m.symbol); return true; });
  }

  getPrice(symbol: string, asOf: string): PITPriceRecord {
    const future = this.data.prices.find(
      x => x.symbol === symbol && x.timestamp.slice(0, 10) === asOf.slice(0, 10) && x.availableAt > asOf
    );
    if (future) this.guard(future, asOf, "PRICE", symbol);

    const p = this.data.prices
      .filter(x => x.symbol === symbol && x.timestamp <= asOf)
      .sort((a,b) => b.timestamp.localeCompare(a.timestamp))[0];
    if (!p) return this.missing("PRICE", `No PIT price for ${symbol} at ${asOf}`, symbol, asOf);
    this.guard(p, asOf, "PRICE", symbol);
    return p;
  }

  getEodPrice(symbol: string, date: string, asOf: string): PITPriceRecord {
    const available = eodAvailabilityTimestamp(date, this.eodAnchor);
    if (asOf < available) {
      throw new PITLookaheadError(
        `EOD OHLCV is not available before ${available}`, `${symbol}:${date}`, available, asOf
      );
    }
    const p = this.data.prices.find(x =>
      x.symbol === symbol && x.timestamp === available
    );
    if (!p) return this.missing("PRICE", `Missing EOD OHLCV ${symbol} ${date}`, symbol, asOf);
    this.guard(p, asOf, "PRICE", symbol);
    return p;
  }

  getFundamental(symbol: string, asOf: string) {
    const all = this.data.fundamentals
      .filter(f => f.kind === "FUNDAMENTAL" && f.symbol === symbol)
      .map(f => ({f, availableAt:filingAvailableAt(f,this.fallbackLagDays)}));
    const future = all.find(x => x.availableAt > asOf);
    const valid = all
      .filter(x => x.availableAt <= asOf)
      .sort((a,b) => b.availableAt.localeCompare(a.availableAt));
    if (!valid.length && future) {
      this.guard({...future.f, availableAt: future.availableAt}, asOf, "FUNDAMENTAL", symbol);
    }
    const x = valid[0];
    if (!x) return this.missing("FUNDAMENTAL", `No knowable fundamental for ${symbol}`, symbol, asOf);
    const out = {...x.f, availableAt:x.availableAt};
    this.guard(out, asOf, "FUNDAMENTAL", symbol);
    return out;
  }

  getShareholding(symbol: string, asOf: string) {
    const all = this.data.fundamentals
      .filter(f => f.kind === "SHAREHOLDING" && f.symbol === symbol)
      .map(f => ({f, availableAt:filingAvailableAt(f,this.fallbackLagDays)}));
    const future = all.find(x => x.availableAt > asOf);
    const valid = all
      .filter(x => x.availableAt <= asOf)
      .sort((a,b) => b.availableAt.localeCompare(a.availableAt));
    if (!valid.length && future) {
      this.guard({...future.f, availableAt: future.availableAt}, asOf, "SHAREHOLDING", symbol);
    }
    const x = valid[0];
    if (!x) return this.missing("SHAREHOLDING", `No knowable shareholding for ${symbol}`, symbol, asOf);
    const out = {...x.f, availableAt:x.availableAt};
    this.guard(out, asOf, "SHAREHOLDING", symbol);
    return out;
  }

  getCorporateActions(symbol: string, asOf: string) {
    return this.data.corporateActions
      .filter(a => a.symbol === symbol && a.exDate <= asOf.slice(0,10))
      .filter(a => { this.guard(a, asOf, "CORPORATE_ACTION", symbol); return true; })
      .sort((a,b) => a.exDate.localeCompare(b.exDate));
  }

  getBackwardAdjustedPrice(symbol: string, tradingDate: string, asOf: string) {
    const raw = this.data.prices.find(
      p => p.symbol === symbol && p.timestamp.slice(0,10) === tradingDate
    );
    if (!raw) return this.missing("PRICE", `Missing raw price ${symbol}/${tradingDate}`, symbol, asOf);
    this.guard(raw, asOf, "PRICE", symbol);

    let factor = 1;
    for (const a of this.getCorporateActions(symbol, asOf)) {
      if (a.exDate > tradingDate && (a.actionType === "SPLIT" || a.actionType === "BONUS")) {
        factor *= (a.ratioDenominator ?? 1) / (a.ratioNumerator ?? 1);
      }
    }
    return {
      ...raw,
      open:raw.open*factor, high:raw.high*factor,
      low:raw.low*factor, close:raw.close*factor,
      raw:false, adjusted:true
    };
  }

  assertCleanRun() {
    const contamination = this.events.filter(x =>
      x.event === "FAIL" && x.reason === "FUTURE_READ"
    );
    if (contamination.length) {
      throw new PITLookaheadError(
        `PIT run contaminated: ${contamination.length} future read(s)`
      );
    }
  }

  snapshotHash(asOf: string) {
    return sha256Canonical({
      asOf,
      securities:this.getSecurities(asOf),
      memberships:this.getIndexMembers("NIFTY50",asOf),
      prices:this.data.prices.filter(p=>p.timestamp<=asOf),
      corporateActions:this.data.corporateActions.filter(a=>a.exDate<=asOf.slice(0,10)),
      fundamentals:this.data.fundamentals.filter(f=>filingAvailableAt(f,this.fallbackLagDays)<=asOf)
    });
  }
}

import type { ResearchMetrics } from "./types";

export type GateResult = "PROMOTE" | "RETAIN AS RISK CONTROL" | "REJECT/REVISE";

export interface GateInput {
  metrics:ResearchMetrics;
  bootstrap:{pPositive:number;pAbove020:number;lower:number};
  sampleMin?:number;
  maxDrawdownPct?:number;
  calmarMin?:number;
  regimeRobust?:boolean;
  twoXSlippageStable?:boolean;
}

export function evaluateGate(x: GateInput): GateResult {
  const n = x.sampleMin ?? 150;
  const dd = x.maxDrawdownPct ?? 20;
  const calmar = x.calmarMin ?? 1;

  if (x.metrics.trades < n) return "REJECT/REVISE";

  // Tier 1: Full Promotion
  if (
    x.metrics.expectancyR >= 0.20 &&
    x.metrics.profitFactor >= 1.40 &&
    x.metrics.maxDrawdownPct <= dd &&
    x.metrics.calmar >= calmar &&
    x.bootstrap.pPositive >= 0.85
  ) {
    if (!x.regimeRobust || !x.twoXSlippageStable) {
      return "RETAIN AS RISK CONTROL";
    }
    return "PROMOTE";
  }

  // Tier 2: Capital Protection / Tail Risk Reduction
  if (
    x.metrics.maxDrawdownPct <= dd &&
    (x.regimeRobust || x.twoXSlippageStable) &&
    x.metrics.expectancyR >= 0
  ) {
    return "RETAIN AS RISK CONTROL";
  }

  return "REJECT/REVISE";
}

/**
 * RESEARCH MANIFEST ENGINE (PIT Research Engine)
 * Milestone: v6.3.0-R1
 *
 * Enforces the v6.2.0-FROZEN code freeze, verifies file integrity against the canonical
 * baseline manifest, and produces reproducible ResearchRunManifest instances.
 */

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

export interface ResearchRunManifest {
  runId: string;
  parentVersion: 'v6.2.0-FROZEN';
  codeCommit?: string;
  codeHash: string;
  configHash: string;
  universeHash: string;
  corporateActionHash: string;
  costModelHash: string;
  timezone: 'Asia/Kolkata';
  calendarVersion: string;
  createdAt: string;
}

export interface BaselineIntegrityVerification {
  isBaselineUnmodified: boolean;
  tamperedFiles: string[];
  manifestPath: string;
  timestamp: string;
}

export class ResearchManifestEngine {
  private static instance: ResearchManifestEngine;
  private rootDir: string;

  constructor(rootDir?: string) {
    this.rootDir = rootDir || path.resolve(process.cwd());
  }

  public static getInstance(): ResearchManifestEngine {
    if (!ResearchManifestEngine.instance) {
      ResearchManifestEngine.instance = new ResearchManifestEngine();
    }
    return ResearchManifestEngine.instance;
  }

  /**
   * Computes SHA-256 hash for a file relative to workspace root.
   */
  public computeFileHash(relPath: string): string {
    const fullPath = path.resolve(this.rootDir, relPath);
    if (!fs.existsSync(fullPath)) {
      throw new Error(`Target file not found for hashing: ${relPath}`);
    }
    const buf = fs.readFileSync(fullPath);
    return crypto.createHash('sha256').update(buf).digest('hex');
  }

  /**
   * Verifies that the frozen v6.2 core strategy and risk files have NOT been modified.
   */
  public verifyBaselineFreeze(): BaselineIntegrityVerification {
    const manifestPath = path.resolve(this.rootDir, 'data', 'v6.2.0_frozen_manifest.json');
    if (!fs.existsSync(manifestPath)) {
      throw new Error(`Canonical frozen manifest not found at: ${manifestPath}`);
    }

    const manifestData = JSON.parse(fs.readFileSync(manifestPath, 'utf-8'));
    const tampered: string[] = [];

    const FROZEN_PRODUCTION_FILES = [
      'src/server/services/PureTechnicalStrategiesEngine.ts',
      'src/server/services/StrategyParameterConfig.ts',
      'src/server/services/SignalQualityOverlay.ts',
      'src/server/services/CapitalProtectionEngine.ts',
      'src/server/services/NewTechnicalStrategiesEngine.ts'
    ];

    for (const file of FROZEN_PRODUCTION_FILES) {
      const recorded = manifestData.files[file];
      if (!recorded || !recorded.sha256) {
        tampered.push(`${file} (missing in manifest)`);
        continue;
      }
      const currentHash = this.computeFileHash(file);
      if (currentHash !== recorded.sha256) {
        tampered.push(`${file} (hash mismatch: expected ${recorded.sha256}, got ${currentHash})`);
      }
    }

    return {
      isBaselineUnmodified: tampered.length === 0,
      tamperedFiles: tampered,
      manifestPath,
      timestamp: new Date().toISOString()
    };
  }

  /**
   * Creates a formal ResearchRunManifest fingerprinting code, config, universe, and cost model.
   */
  public createRunManifest(params: {
    runId: string;
    universeDefinition: string[];
    corporateActionCount: number;
    costModelVersion?: string;
  }): ResearchRunManifest {
    const integrity = this.verifyBaselineFreeze();
    if (!integrity.isBaselineUnmodified) {
      throw new Error(
        `Cannot initialize research run: v6.2.0-FROZEN baseline violated: ${integrity.tamperedFiles.join(', ')}`
      );
    }

    const codeHasher = crypto.createHash('sha256');
    const filesToHash = [
      'src/server/services/PureTechnicalStrategiesEngine.ts',
      'src/server/services/StrategyParameterConfig.ts',
      'src/server/services/SignalQualityOverlay.ts',
      'src/server/services/CapitalProtectionEngine.ts',
      'src/server/services/NewTechnicalStrategiesEngine.ts'
    ];
    for (const f of filesToHash) {
      codeHasher.update(this.computeFileHash(f));
    }
    const codeHash = codeHasher.digest('hex');

    const universeHash = crypto
      .createHash('sha256')
      .update(params.universeDefinition.sort().join(','))
      .digest('hex');

    const corporateActionHash = crypto
      .createHash('sha256')
      .update(`CA_COUNT:${params.corporateActionCount}`)
      .digest('hex');

    const costModelHash = crypto
      .createHash('sha256')
      .update(params.costModelVersion || 'NSE_STATUTORY_V1_2026')
      .digest('hex');

    const configHash = crypto
      .createHash('sha256')
      .update(`CALENDAR:NSE_2020_2026_CANONICAL|TZ:Asia/Kolkata`)
      .digest('hex');

    return {
      runId: params.runId,
      parentVersion: 'v6.2.0-FROZEN',
      codeHash,
      configHash,
      universeHash,
      corporateActionHash,
      costModelHash,
      timezone: 'Asia/Kolkata',
      calendarVersion: 'NSE_2020_2026_CANONICAL',
      createdAt: new Date().toISOString()
    };
  }
}

import sqlite3 from "sqlite3";
import crypto from "node:crypto";
import fs from "node:fs";

export interface PreflightResult {
  databasePath: string;
  databaseSha256: string;
  integrityCheck: string;
  foreignKeyErrors: number;
  dailyBars: number;
  symbols: number;
  dateMin: string | null;
  dateMax: string | null;

  deliveryRows: number;
  turnoverRows: number;

  calendarRows: number;
  calendarTradingRows: number;

  indexConstituentRows: number;
  corporateActionRows: number;
  corporateActionExDateRows: number;

  shareholdingRows: number;
  shareholdingAsOfRows: number;

  financialRows: number;
  financialPeriodRows: number;
}

function all<T>(
  db: sqlite3.Database,
  sql: string
): Promise<T[]> {
  return new Promise((resolve, reject) => {
    db.all<T>(sql, (err, rows) => {
      if (err) reject(err);
      else resolve(rows);
    });
  });
}

function sha256File(filePath: string): string {
  const hash = crypto.createHash("sha256");
  const fd = fs.openSync(filePath, "r");

  try {
    const buffer = Buffer.allocUnsafe(1024 * 1024);
    let bytesRead: number;

    do {
      bytesRead = fs.readSync(
        fd,
        buffer,
        0,
        buffer.length,
        null
      );

      if (bytesRead > 0) {
        hash.update(
          buffer.subarray(
            0,
            bytesRead
          )
        );
      }
    } while (bytesRead === buffer.length);

    return hash.digest("hex");
  } finally {
    fs.closeSync(fd);
  }
}

export async function runResearchPreflight(
  dbPath: string
): Promise<PreflightResult> {
  const db =
    new sqlite3.Database(
      dbPath,
      sqlite3.OPEN_READONLY
    );

  try {
    const integrity =
      await all<{ integrity_check: string }>(
        db,
        `PRAGMA integrity_check`
      );

    const integrityCheck =
      String(
        integrity[0]?.integrity_check ?? ""
      );

    if (integrityCheck !== "ok") {
      throw new Error(
        `SQLITE_INTEGRITY_CHECK_FAILED: ${integrityCheck}`
      );
    }

    const fk =
      await all<Record<string, unknown>>(
        db,
        `PRAGMA foreign_key_check`
      );

    if (fk.length > 0) {
      throw new Error(
        `SQLITE_FOREIGN_KEY_CHECK_FAILED: ${fk.length} errors`
      );
    }

    const counts =
      await all<{
        dailyBars: number;
        symbols: number;
        dateMin: string;
        dateMax: string;
        deliveryRows: number;
        turnoverRows: number;
        calendarRows: number;
        calendarTradingRows: number;
        indexConstituentRows: number;
        corporateActionRows: number;
        corporateActionExDateRows: number;
        shareholdingRows: number;
        shareholdingAsOfRows: number;
        financialRows: number;
        financialPeriodRows: number;
      }>(
        db,
        `
        SELECT
          (SELECT COUNT(*) FROM DailyOHLCV) AS dailyBars,
          (SELECT COUNT(DISTINCT symbol) FROM DailyOHLCV) AS symbols,
          (SELECT MIN(trade_date) FROM DailyOHLCV) AS dateMin,
          (SELECT MAX(trade_date) FROM DailyOHLCV) AS dateMax,

          (SELECT COUNT(*) FROM DailyOHLCV
             WHERE delivery_qty IS NOT NULL) AS deliveryRows,

          (SELECT COUNT(*) FROM DailyOHLCV
             WHERE turnover IS NOT NULL) AS turnoverRows,

          (SELECT COUNT(*) FROM trading_calendar) AS calendarRows,

          (SELECT COUNT(*) FROM trading_calendar
             WHERE is_trading_day = 1) AS calendarTradingRows,

          (SELECT COUNT(*) FROM IndexConstituents)
             AS indexConstituentRows,

          (SELECT COUNT(*) FROM CorporateActions)
             AS corporateActionRows,

          (SELECT COUNT(*) FROM CorporateActions
             WHERE ex_date IS NOT NULL)
             AS corporateActionExDateRows,

          (SELECT COUNT(*) FROM HistoricalShareholdingPattern)
             AS shareholdingRows,

          (SELECT COUNT(*) FROM HistoricalShareholdingPattern
             WHERE as_of_date IS NOT NULL)
             AS shareholdingAsOfRows,

          (SELECT COUNT(*) FROM HistoricalFinancialStatements)
             AS financialRows,

          (SELECT COUNT(*) FROM HistoricalFinancialStatements
             WHERE period_date IS NOT NULL)
             AS financialPeriodRows
        `
      );

    const c = counts[0];

    const result: PreflightResult = {
      databasePath: dbPath,
      databaseSha256: sha256File(dbPath),

      integrityCheck,
      foreignKeyErrors: fk.length,

      dailyBars: Number(c.dailyBars),
      symbols: Number(c.symbols),
      dateMin: c.dateMin ?? null,
      dateMax: c.dateMax ?? null,

      deliveryRows: Number(c.deliveryRows),
      turnoverRows: Number(c.turnoverRows),

      calendarRows: Number(c.calendarRows),
      calendarTradingRows:
        Number(c.calendarTradingRows),

      indexConstituentRows:
        Number(c.indexConstituentRows),

      corporateActionRows:
        Number(c.corporateActionRows),

      corporateActionExDateRows:
        Number(c.corporateActionExDateRows),

      shareholdingRows:
        Number(c.shareholdingRows),

      shareholdingAsOfRows:
        Number(c.shareholdingAsOfRows),

      financialRows:
        Number(c.financialRows),

      financialPeriodRows:
        Number(c.financialPeriodRows)
    };

    return result;
  } finally {
    db.close();
  }
}

export function assertResearchDataComplete(
  p: PreflightResult
) {
  const failures: string[] = [];

  if (p.deliveryRows < p.dailyBars) {
    failures.push(
      `DELIVERY_DATA_INCOMPLETE: ${p.deliveryRows}/${p.dailyBars}`
    );
  }

  if (p.turnoverRows < p.dailyBars) {
    failures.push(
      `TURNOVER_DATA_INCOMPLETE: ${p.turnoverRows}/${p.dailyBars}`
    );
  }

  if (p.calendarTradingRows === 0) {
    failures.push(
      "TRADING_CALENDAR_UNAVAILABLE"
    );
  }

  if (p.indexConstituentRows === 0) {
    failures.push(
      "HISTORICAL_INDEX_MEMBERSHIP_UNAVAILABLE"
    );
  }

  if (
    p.corporateActionRows > 0 &&
    p.corporateActionExDateRows === 0
  ) {
    failures.push(
      "CORPORATE_ACTION_EX_DATE_UNAVAILABLE"
    );
  }

  if (
    p.shareholdingRows > 0 &&
    p.shareholdingAsOfRows === 0
  ) {
    failures.push(
      "SHAREHOLDING_AS_OF_DATE_UNAVAILABLE"
    );
  }

  if (
    p.financialRows > 0 &&
    p.financialPeriodRows === 0
  ) {
    failures.push(
      "FINANCIAL_PERIOD_DATE_UNAVAILABLE"
    );
  }

  if (failures.length) {
    throw new Error(
      "DATA_INSUFFICIENT\n" +
      failures.map(x => ` - ${x}`).join("\n")
    );
  }
}

import type {
  ResearchBar,
  TradeIdentityLedger
} from "./types.js";

export type MarketRegime =
  | "BULLISH_EXPANSION"
  | "SIDEWAYS_CONSOLIDATION"
  | "BEARISH_CONTRACTION"
  | "UNCLASSIFIED";

export function classifyRegime(
  bars: ResearchBar[],
  asOf: string
): MarketRegime {
  const history =
    bars
      .filter(
        b =>
          b.timestamp <= asOf
      )
      .sort(
        (a, b) =>
          a.timestamp.localeCompare(
            b.timestamp
          )
      );

  if (history.length < 200) {
    return "UNCLASSIFIED";
  }

  const last = history[history.length - 1];

  const closes20 =
    history
      .slice(-20)
      .map(x => x.close);

  const closes200 =
    history
      .slice(-200)
      .map(x => x.close);

  const ma20 =
    closes20.reduce(
      (a, b) => a + b,
      0
    ) / closes20.length;

  const ma200 =
    closes200.reduce(
      (a, b) => a + b,
      0
    ) / closes200.length;

  const first200 =
    closes200[0];

  const trend =
    last.close / first200 - 1;

  const volatility =
    closes20.length > 1
      ? Math.sqrt(
          closes20
            .slice(1)
            .map(
              (x, i) =>
                Math.pow(
                  x /
                    closes20[i] -
                    1,
                  2
                )
            )
            .reduce(
              (a, b) => a + b,
              0
            ) /
            (closes20.length - 1)
        )
      : 0;

  if (
    last.close > ma200 &&
    ma20 > ma200 &&
    trend > 0.05
  ) {
    return "BULLISH_EXPANSION";
  }

  if (
    last.close < ma200 &&
    ma20 < ma200 &&
    trend < -0.05
  ) {
    return "BEARISH_CONTRACTION";
  }

  if (volatility < 0.03) {
    return "SIDEWAYS_CONSOLIDATION";
  }

  return "UNCLASSIFIED";
}

export function attributeTradeRegimes(
  trades: TradeIdentityLedger[],
  bars: ResearchBar[]
) {
  return trades.map(
    trade => ({
      ...trade,
      regime:
        classifyRegime(
          bars.filter(
            b =>
              b.symbol === trade.symbol
          ),
          trade.signalTimestamp
        )
    })
  );
}

import type { ResearchMetrics, TradeIdentityLedger } from "./types.js";

export interface EquityPoint {
  timestamp: string;
  equity: number;
}

export interface MetricOptions {
  initialCapital?: number;
  equity?: EquityPoint[];
}

export function percentile(xs: number[], p: number): number {
  if (!xs.length) return 0;

  const a = [...xs].sort((x, y) => x - y);
  const i = (a.length - 1) * p;
  const lo = Math.floor(i);
  const hi = Math.ceil(i);

  return lo === hi
    ? a[lo]
    : a[lo] + (a[hi] - a[lo]) * (i - lo);
}

export function bootstrapExpectancy(
  rMultiples: number[],
  iterations = 1000,
  seed = 42
) {
  if (!rMultiples.length) {
    return {
      lower: 0,
      median: 0,
      upper: 0,
      pPositive: 0,
      pAbove020: 0
    };
  }

  let state = seed >>> 0;

  const rand = () => {
    state = (1664525 * state + 1013904223) >>> 0;
    return state / 4294967296;
  };

  const means: number[] = [];

  for (let i = 0; i < iterations; i++) {
    let sum = 0;

    for (let j = 0; j < rMultiples.length; j++) {
      sum += rMultiples[Math.floor(rand() * rMultiples.length)];
    }

    means.push(sum / rMultiples.length);
  }

  return {
    lower: percentile(means, 0.025),
    median: percentile(means, 0.50),
    upper: percentile(means, 0.975),
    pPositive: means.filter(x => x > 0).length / means.length,
    pAbove020: means.filter(x => x > 0.20).length / means.length
  };
}

function buildTradeEquity(
  trades: TradeIdentityLedger[],
  initialCapital: number
): EquityPoint[] {
  const ordered = [...trades]
    .filter(t => Number.isFinite(t.netPnl))
    .sort((a, b) => a.exitTimestamp.localeCompare(b.exitTimestamp));

  let equity = initialCapital;

  return ordered.map(t => {
    equity += Number(t.netPnl ?? 0);

    return {
      timestamp: t.exitTimestamp,
      equity
    };
  });
}

function maxDrawdownPct(equity: EquityPoint[]): number {
  if (!equity.length) return 0;

  let peak = equity[0].equity;
  let maxDd = 0;

  for (const point of equity) {
    peak = Math.max(peak, point.equity);

    if (peak > 0) {
      const dd = ((peak - point.equity) / peak) * 100;
      maxDd = Math.max(maxDd, dd);
    }
  }

  return maxDd;
}

function annualizedReturn(
  equity: EquityPoint[],
  initialCapital: number
): number {
  if (equity.length < 2 || initialCapital <= 0) return 0;

  const start = new Date(equity[0].timestamp).getTime();
  const end = new Date(equity[equity.length - 1].timestamp).getTime();

  const years = Math.max(
    (end - start) / (365.25 * 24 * 60 * 60 * 1000),
    1 / 365.25
  );

  const ending = equity[equity.length - 1].equity;

  if (ending <= 0) return -1;

  return Math.pow(ending / initialCapital, 1 / years) - 1;
}

function dailyReturns(equity: EquityPoint[]): number[] {
  if (equity.length < 2) return [];

  const out: number[] = [];

  for (let i = 1; i < equity.length; i++) {
    const previous = equity[i - 1].equity;
    const current = equity[i].equity;

    if (previous > 0) {
      out.push(current / previous - 1);
    }
  }

  return out;
}

function sortinoRatio(equity: EquityPoint[]): number {
  const returns = dailyReturns(equity);

  if (!returns.length) return 0;

  const mean =
    returns.reduce((a, b) => a + b, 0) / returns.length;

  const downside = returns
    .filter(r => r < 0)
    .map(r => r * r);

  if (!downside.length) {
    return mean > 0 ? Infinity : 0;
  }

  const downsideDeviation =
    Math.sqrt(
      downside.reduce((a, b) => a + b, 0) / returns.length
    );

  if (downsideDeviation === 0) return 0;

  return (mean / downsideDeviation) * Math.sqrt(252);
}

export function calculateMetrics(
  trades: TradeIdentityLedger[],
  options: MetricOptions = {}
): ResearchMetrics {
  const initialCapital = options.initialCapital ?? 10_000_000;

  const rs = trades.map(t => Number(t.netRMultiple ?? 0));
  const pnls = trades.map(t => Number(t.netPnl ?? 0));

  const wins = pnls.filter(x => x > 0);
  const losses = pnls.filter(x => x < 0);

  const grossWin = wins.reduce((a, b) => a + b, 0);
  const grossLoss = Math.abs(losses.reduce((a, b) => a + b, 0));

  const equity =
    options.equity?.length
      ? [...options.equity].sort(
          (a, b) => a.timestamp.localeCompare(b.timestamp)
        )
      : buildTradeEquity(trades, initialCapital);

  const dd = maxDrawdownPct(equity);
  const cagr = annualizedReturn(equity, initialCapital);

  return {
    trades: trades.length,

    netPnl: pnls.reduce((a, b) => a + b, 0),

    expectancyR:
      rs.length
        ? rs.reduce((a, b) => a + b, 0) / rs.length
        : 0,

    profitFactor:
      grossLoss > 0
        ? grossWin / grossLoss
        : grossWin > 0
          ? Infinity
          : 0,

    maxDrawdownPct: Number(dd.toFixed(6)),

    calmar:
      dd > 0
        ? Number(((cagr * 100) / dd).toFixed(6))
        : 0,

    sortino: Number(sortinoRatio(equity).toFixed(6)),

    winRate:
      pnls.length
        ? wins.length / pnls.length
        : 0,

    meanMAE:
      trades.length
        ? trades.reduce(
            (a, t) => a + Number(t.mae ?? 0),
            0
          ) / trades.length
        : 0,

    meanMFE:
      trades.length
        ? trades.reduce(
            (a, t) => a + Number(t.mfe ?? 0),
            0
          ) / trades.length
        : 0
  };
}

