export class TradingCalendarService {
  private static instance: TradingCalendarService;
  private dbSessionMap = new Map<string, MarketSession>();

  public static getInstance(): TradingCalendarService {
    if (!TradingCalendarService.instance) {
      TradingCalendarService.instance = new TradingCalendarService();
    }
    return TradingCalendarService.instance;
  }

  /**
   * Load authoritative sessions directly from database or fixture
   */
  public loadFromSessions(sessions: MarketSession[]): void {
    for (const s of sessions) {
      this.dbSessionMap.set(s.date, s);
    }
  }

  /**
   * Determine whether a given YYYY-MM-DD date is an active trading session.
   */
  public isTradingDay(dateStr: string): boolean {
    const session = this.getSessionInfo(dateStr);
    return session.isTradingDay;
  }

  /**
   * Full session details for a given date.
   */
  public getSessionInfo(dateStr: string): MarketSession {
    if (this.dbSessionMap.has(dateStr)) {
      return this.dbSessionMap.get(dateStr)!;
    }

    const d = new Date(`${dateStr}T00:00:00Z`);
    const dayOfWeek = d.getUTCDay(); // 0 = Sunday, 6 = Saturday

    const holiday = NSE_CALENDAR_MAP[dateStr];

    if (holiday) {
      if (holiday.type === 'MUHURAT') {
        return {
          date: dateStr,
          isTradingDay: true,
          sessionType: 'MUHURAT',
          holidayName: holiday.name,
          openTimeIST: '18:15',
          closeTimeIST: '19:15'
        };
      }
      return {
        date: dateStr,
        isTradingDay: false,
        sessionType: 'CLOSED',
        holidayName: holiday.name,
        openTimeIST: '00:00',
        closeTimeIST: '00:00'
      };
    }

    // Standard Weekend check
    if (dayOfWeek === 0 || dayOfWeek === 6) {
      return {
        date: dateStr,
        isTradingDay: false,
        sessionType: 'CLOSED',
        holidayName: dayOfWeek === 0 ? 'Sunday' : 'Saturday',
        openTimeIST: '00:00',
        closeTimeIST: '00:00'
      };
    }

    // Regular trading day
    return {
      date: dateStr,
      isTradingDay: true,
      sessionType: 'REGULAR',
      openTimeIST: '09:15',
      closeTimeIST: '15:30'
    };
  }

  /**
   * Returns the next valid trading day strictly after dateStr.
   * NEVER uses date + 1.
   */
  public getNextTradingDay(dateStr: string): string {
    let curr = new Date(`${dateStr}T00:00:00Z`);
    while (true) {
      curr.setUTCDate(curr.getUTCDate() + 1);
      const nextStr = curr.toISOString().split('T')[0];
      if (this.isTradingDay(nextStr)) {
        return nextStr;
      }
    }
  }

  /**
   * Returns the previous valid trading day strictly before dateStr.
   */
  public getPrevTradingDay(dateStr: string): string {
    let curr = new Date(`${dateStr}T00:00:00Z`);
    while (true) {
      curr.setUTCDate(curr.getUTCDate() - 1);
      const prevStr = curr.toISOString().split('T')[0];
      if (this.isTradingDay(prevStr)) {
        return prevStr;
      }
    }
  }

  /**
   * Returns list of all active trading days in range [startDate, endDate] inclusive.
   */
  public getTradingDaysBetween(startDate: string, endDate: string): string[] {
    const res: string[] = [];
    let curr = new Date(`${startDate}T00:00:00Z`);
    const end = new Date(`${endDate}T00:00:00Z`);

    while (curr <= end) {
      const dStr = curr.toISOString().split('T')[0];
      if (this.isTradingDay(dStr)) {
        res.push(dStr);
      }
      curr.setUTCDate(curr.getUTCDate() + 1);
    }
    return res;
  }
}

import type { ExecutionConfig } from "./types.js";

export interface CostBreakdown {
  brokerage: number;
  stt: number;
  exchangeTxn: number;
  stampDuty: number;
  gst: number;

  // These are informational only.
  // They are applied to execution price by ExecutionSimulator.
  slippage: number;
  impact: number;

  statutoryTotal: number;
  total: number;
}

export class TransactionCostEngine {
  constructor(private readonly c: ExecutionConfig) {}

  estimate(
    side: "BUY" | "SELL",
    price: number,
    quantity: number
  ): CostBreakdown {
    const value = Math.abs(price * quantity);

    const brokerage = Math.min(
      this.c.brokeragePerLeg,
      value
    );

    // Delivery STT: sell side.
    const stt =
      side === "SELL"
        ? value * this.c.sttRate
        : 0;

    const exchangeTxn =
      value * this.c.exchangeTxnRate;

    const stampDuty =
      side === "BUY"
        ? value * this.c.stampDutyBuyRate
        : 0;

    const gst =
      (brokerage + exchangeTxn) *
      this.c.gstRate;

    const statutoryTotal =
      brokerage +
      stt +
      exchangeTxn +
      stampDuty +
      gst;

    return {
      brokerage,
      stt,
      exchangeTxn,
      stampDuty,
      gst,

      slippage: 0,
      impact: 0,

      statutoryTotal,
      total: statutoryTotal
    };
  }

  executionPrice(
    side: "BUY" | "SELL",
    requestedPrice: number,
    quantity: number,
    participationPct: number
  ): {
    fillPrice: number;
    slippage: number;
    impact: number;
  } {
    const value =
      Math.abs(requestedPrice * quantity);

    const slippageRate =
      this.c.slippageBps / 10_000;

    const participation =
      Math.max(
        0,
        participationPct
      );

    const impactMultiplier =
      Math.max(
        0,
        participation /
          Math.max(
            this.c.maxParticipationPct,
            1e-9
          )
      );

    const impactRate =
      (this.c.impactBps / 10_000) *
      impactMultiplier;

    const adverseRate =
      slippageRate +
      impactRate;

    const fillPrice =
      side === "BUY"
        ? requestedPrice * (1 + adverseRate)
        : requestedPrice * (1 - adverseRate);

    return {
      fillPrice,
      slippage: value * slippageRate,
      impact: value * impactRate
    };
  }
}

export type Direction = "LONG" | "SHORT" | "EXIT" | "HEDGE";
export type ExperimentArm = "A_RAW" | "B_V62_OVERLAY" | "C_CAPITAL_PROTECTION" | "C_CHALLENGERS" | "D_RISK_ORACLE" | "D_UNEXPOSED";
export type AblationLayer =
  | "RAW" | "SIGNAL_QUALITY" | "RISK_SIZING" | "GAP_RISK"
  | "CAPITAL_PROTECTION" | "EXIT_FRAMEWORK" | "ALL";

export interface ResearchBar {
  symbol: string;
  timestamp: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  deliveryVolume: number;
  tradable: boolean;
  upperCircuit?: number;
  lowerCircuit?: number;
  availableAt: string;

  // Compatibility aliases
  date?: string;
  turnover?: number;
  deliveryQty?: number;
}

export interface SignalProvenance {
  dataMode: "REAL_HISTORICAL";
  decisionTimestamp: string;
  availableAt: string;
  sourceTables: string[];
  sourceRecordIds: string[];
  parameterHash: string;
  productionBaselineHash: string;
}

export interface ResearchSignal {
  signalId: string;
  strategyId: string;
  symbol: string;
  timestamp: string;
  availableAt?: string;
  direction: Direction;
  entry: number;
  stop: number;
  target?: number;
  quantityHint?: number;
